.dl {font-family:var(--font-sans);-webkit-font-smoothing:antialiased;letter-spacing:var(--tracking-snug);box-sizing:border-box;--sh-card:0 0 0 1px rgb(0 0 0/.3);--sh-plate:0 .5px 1px 1px rgb(0 0 0/.3);--sh-overlay:0 3px 8px rgb(0 0 0/.13),0 2px 5px rgb(0 0 0/.13),0 1px 1px rgb(0 0 0/.13);position:relative;display:flex;width:100%;max-width:512px;flex-direction:column;overflow-y:auto;border-radius:var(--radius-xl);border:var(--spacing-hairline) solid var(--color-border-2);background:var(--color-popover);text-align:left;box-shadow:var(--sh-overlay);color:var(--color-foreground)}
:where([data-doop-theme="light"]) .dl {--sh-card:0 0 0 .5px rgb(0 0 0/.11);--sh-plate:0 1px 2px rgb(0 0 0/.05);--sh-overlay:0 6px 18px rgb(0 0 0/.03),0 3px 9px rgb(0 0 0/.04),0 1px 1px rgb(0 0 0/.05);}
.dl .hd {display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:12px;padding:16px 20px 0}
.dl .t {grid-column:1;grid-row:1;align-self:center;text-wrap:balance;font-weight:var(--font-weight-medium);font-size:var(--text-base);letter-spacing:var(--tracking-tight)}
.dl[data-size="xl"] .t {font-size:var(--text-xl)}
.dl .hd .btn {grid-column:2;grid-row:1;margin-top:-2px;margin-right:-6px;align-self:start;justify-self:end;color:var(--color-icon-muted)}
.dl .d {grid-column:1/-1;grid-row:2;margin-top:4px;text-wrap:pretty;font-size:var(--text-sm);color:var(--color-muted-foreground-2);line-height:var(--leading-normal)}
.dl .bd {display:flex;flex-direction:column;padding:20px;gap:16px;font-size:var(--text-sm);color:var(--color-muted-foreground-1);line-height:var(--leading-normal)}
.dl[data-spacing="compact"] .bd {gap:12px;padding:16px 20px}
.dl .ft {display:flex;flex-direction:row;justify-content:flex-end;gap:8px;padding:0 20px 16px}
.dl .cl {grid-column:2;grid-row:1;margin-top:-2px;margin-right:-6px;align-self:start;justify-self:end;display:inline-flex;align-items:center;justify-content:center;width:var(--spacing-control-sm);height:var(--spacing-control-sm);border-radius:var(--radius-md);border:var(--spacing-hairline) solid transparent;background:transparent;color:var(--color-icon-muted);cursor:pointer;transition:color 100ms,background-color 100ms;padding:0}
.dl .cl:hover {color:var(--color-foreground);background:var(--color-secondary)}
.dl .cl svg {width:var(--spacing-icon-sm);height:var(--spacing-icon-sm)}
